package toml

import (
	"reflect"
	"testing"
)

func TestDecodeEmptyDocument(t *testing.T) {
	got, err := Decode("")
	if err != nil {
		t.Fatalf("Decode(\"\") returned error: %v", err)
	}
	if want := map[string]any{}; !reflect.DeepEqual(got, want) {
		t.Fatalf("Decode(\"\") = %#v, want %#v", got, want)
	}
}

