// Package toml provides the TOML decoder used by the command-line filter.
package toml

import (
	"fmt"
	"strconv"
	"strings"
)

type scalar struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Decode parses a TOML document and returns its tagged representation.
//
func Decode(input string) (map[string]any, error) {
	result := map[string]any{}
	for lineNumber, line := range strings.Split(input, "\n") {
		line = strings.TrimSpace(strings.SplitN(line, "#", 2)[0])
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") {
			return nil, fmt.Errorf("line %d: tables are not supported yet", lineNumber+1)
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("line %d: expected key-value pair", lineNumber+1)
		}
		key := strings.TrimSpace(parts[0])
		if key == "" {
			return nil, fmt.Errorf("line %d: empty key", lineNumber+1)
		}
		if _, exists := result[key]; exists {
			return nil, fmt.Errorf("line %d: duplicate key %q", lineNumber+1, key)
		}
		value, err := parseScalar(strings.TrimSpace(parts[1]))
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", lineNumber+1, err)
		}
		result[key] = value
	}
	return result, nil
}

func parseScalar(value string) (scalar, error) {
	if value == "true" || value == "false" {
		return scalar{Type: "bool", Value: value}, nil
	}
	if _, err := strconv.ParseInt(value, 10, 64); err == nil {
		return scalar{Type: "integer", Value: value}, nil
	}
	if len(value) >= 2 && ((value[0] == '"' && value[len(value)-1] == '"') || (value[0] == '\'' && value[len(value)-1] == '\'')) {
		if value[0] == '\'' {
			return scalar{Type: "string", Value: value[1 : len(value)-1]}, nil
		}
		decoded, err := strconv.Unquote(value)
		if err != nil {
			return scalar{}, fmt.Errorf("invalid string: %w", err)
		}
		return scalar{Type: "string", Value: decoded}, nil
	}
	return scalar{}, fmt.Errorf("invalid value %q", value)
}
